package com.ieltspath.assessment.infrastructure.persistence.adapter; import com.ieltspath.assessment.domain.entity.SkillScore; import com.ieltspath.assessment.domain.repository.SkillScoreRepository; import com.ieltspath.assessment.infrastructure.persistence.mapper.AssessmentPersistenceMapper; import com.ieltspath.assessment.infrastructure.persistence.repository.SkillScoreJpaRepository; import org.springframework.stereotype.Component; import java.util.*;
@Component public class SkillScoreRepositoryAdapter implements SkillScoreRepository{private final SkillScoreJpaRepository repository;private final AssessmentPersistenceMapper mapper;public SkillScoreRepositoryAdapter(SkillScoreJpaRepository repository,AssessmentPersistenceMapper mapper){this.repository=repository;this.mapper=mapper;}public List<SkillScore> saveAll(List<SkillScore> v){return repository.saveAll(v.stream().map(mapper::toEntity).toList()).stream().map(mapper::toDomain).toList();}public List<SkillScore> findByResultId(UUID id){return repository.findByResultId(id).stream().map(mapper::toDomain).toList();}}
